"""PDF capture (capture-pdf change). Every PDF here is generated by pdffixture; all text is invented."""

from __future__ import annotations

import re
from collections import Counter

import pytest

from llmwiki import pdf
from llmwiki.errors import WikiError
from pdffixture import (LEFT, TITLE, Page, image_only_pages, paper_pages, pdf_bytes, two_column_pages,
                        width, write_pdf)


@pytest.fixture
def paper(tmp_path):
    return write_pdf(tmp_path / "paper.pdf", paper_pages(), {"Title": "Paper v33", "Author": "jdoe",
                                                            "CreationDate": "D:20260620120000Z"})


def body_of(path) -> str:
    return pdf.extract(path).body


# --- 1.3 the fixture writer -------------------------------------------------------------


def test_fixture_readable_by_pdfminer(tmp_path):
    from pdfminer.high_level import extract_pages
    from pdfminer.layout import LTChar

    p = write_pdf(tmp_path / "two.pdf", [Page().text(72, 700, "Hello there", size=14),
                                         Page().text(72, 700, "Second page", size=9)])
    sizes = []
    for page in extract_pages(p):
        sizes.append({round(c.size) for box in page for line in box for c in line if isinstance(c, LTChar)})
    assert sizes == [{14}, {9}]


# --- 2.1 lines ------------------------------------------------------------------------


def test_right_aligned_lines_in_reading_order_and_superscript_attached(tmp_path):
    p = Page()
    p.text(540 - width("An invented epigraph line one", 12), 700, "An invented epigraph line one")
    p.text(540 - width("and a second epigraph line", 12), 686, "and a second epigraph line")
    p.run(LEFT, 650, [("A sentence with a marker", 12, "R", 0), ("7", 7, "R", 4), (" inside it", 12, "R", 0)])
    for i in range(8):
        p.text(LEFT, 620 - 14 * i, f"filler line number {i} of invented text for the body statistics")
    info, pages = pdf._open(write_pdf(tmp_path / "e.pdf", [p]))
    lines = [ln.text for ln in pdf._lines(pages, 12)]
    assert lines[:3] == ["An invented epigraph line one", "and a second epigraph line",
                         f"A sentence with a marker{pdf.SUP_OPEN}7{pdf.SUP_CLOSE} inside it"]


def test_aligned_short_lines_keep_their_line_breaks(tmp_path):
    p = Page()
    for i, line in enumerate(("An invented epigraph line one", "and a second epigraph line", "-Nobody Invented")):
        p.text(540 - width(line, 12), 700 - 14 * i, line)
    for i in range(10):
        p.text(LEFT, 640 - 14 * i, f"filler line number {i} of invented text for the body statistics and more words")
    body = body_of(write_pdf(tmp_path / "e.pdf", [p]))
    assert "\n\nAn invented epigraph line one\nand a second epigraph line\n-Nobody Invented\n\n" in body


def _body_page(p: Page, top: float = 640, n: int = 10) -> Page:
    for i in range(n):
        p.text(LEFT, top - 14 * i, f"filler line number {i} of invented text for the body statistics and more words")
    return p


def test_rotated_margin_stamp_ignored(tmp_path):
    p = _body_page(Page().vertical(30, 200, "stamp:0000.00000v1 [cs.XX] 1 Jan 2026"))
    assert "stamp" not in body_of(write_pdf(tmp_path / "r.pdf", [p]))


def test_author_year_references_split_by_hanging_indent(tmp_path):
    p = _body_page(Page(), top=720, n=6)
    p.text(LEFT, 620, "References", font="B")
    y = 600
    for entry in (["Anna Example and Boris Sample. A long invented title that wraps onto the next", "line. Journal, 2020."],
                  ["Carla Invented. Another invented work. Proceedings of Nothing,", "2021. URL https://example.org/x."]):
        p.text(LEFT, y, entry[0])
        p.text(LEFT + 11, y - 14, entry[1])
        y -= 34
    refs = body_of(write_pdf(tmp_path / "ay.pdf", [p])).split("## References\n\n")[1].strip().split("\n\n")
    assert [r.split(".")[0] for r in refs] == ["Anna Example and Boris Sample", "Carla Invented"]
    assert refs[1].endswith("Proceedings of Nothing, 2021. URL https://example.org/x.")


def test_table_of_contents_is_a_list(tmp_path):
    p = Page().text(LEFT, 720, "Contents", font="B")
    p.text(LEFT, 700, "1 Introduction 3", font="B")
    p.text(LEFT + 15, 686, "1.1 Invented Background . . . . . . . . . . 3")
    p.text(LEFT, 672, "2 Discussion 5", font="B")
    p.text(LEFT, 640, "1 Introduction", font="B")
    body = body_of(write_pdf(tmp_path / "toc.pdf", [_body_page(p, top=620)]))
    assert "## Contents\n\n- 1 Introduction 3\n- 1.1 Invented Background 3\n- 2 Discussion 5\n\n## 1 Introduction" in body


def test_body_line_starting_with_markup_is_escaped(tmp_path):
    p = _body_page(Page(), top=720, n=6)
    p.text(LEFT, 620, "> 0. (10)")
    p.text(LEFT, 590, "and the invented text goes on after the displayed equation with more words")
    assert "\n\n\\> 0. (10)\n\n" in body_of(write_pdf(tmp_path / "eq.pdf", [p]))


def test_ligatures_and_whitespace_normalised():
    assert pdf._LIGATURES["ﬁ"] == "fi"


# --- 2.2 / 2.3 structure ------------------------------------------------------------------


def test_structure_preserved(paper):
    body = body_of(paper)
    assert body.startswith(f"# {TITLE}\n")
    for h in ("## Abstract", "## 1. Overview", "## 2. Discussion", "## References"):
        assert f"\n{h}\n" in body
    assert "\n> Figure 1: An invented hedge maze drawn in grey.\n" in body
    assert "speaks about categories[^1] and more of" in body
    assert body.rstrip().endswith("[^1]: A footnote about invented categories.")
    refs = body.split("## References\n\n")[1].split("\n\n[^1]")[0].split("\n\n")
    assert [r.split(" ")[0] for r in refs] == ["1.", "2.", "10."]
    assert refs[0].endswith("Journal of Invented Things, 12(3):45-67, 2020.")


def test_paragraph_across_page_break_and_no_page_numbers(paper):
    body = body_of(paper)
    assert "cut by the page break and continues on the following page without any break at all." in body
    assert not re.search(r"^\d$", body, re.M)


def test_hyphenation_rejoined(paper):
    assert "a short remark about hyphenation in gardens." in body_of(paper)


def test_affiliation_markers_are_not_footnotes(paper):
    assert "Anna Example<sup>1</sup>, Boris Sample<sup>2</sup>" in body_of(paper)


def test_no_text_lost(paper):
    from pdfminer.high_level import extract_text

    def chars(s: str) -> Counter:
        return Counter(c for c in s if not c.isspace())

    raw = extract_text(paper)
    for n in ("1", "2", "3"):  # page numbers are dropped on purpose
        raw = re.sub(rf"(?m)^{n}\s*$", "", raw)
    out = re.sub(r"\[\^(\d+)\]:?|<sup>|</sup>|^#+ |^> ", lambda m: m.group(1) or "", body_of(paper), flags=re.M)
    missing = chars(raw) - chars(out)
    assert missing == Counter({"-": 1}), missing  # the line-end hyphen of "hyphen-ation"


def test_relative_to_body_size(tmp_path):
    small = write_pdf(tmp_path / "s.pdf", paper_pages(body_size=10))
    body = body_of(small)
    for h in ("## Abstract", "## 1. Overview", "## References"):
        assert f"\n{h}\n" in body
    assert "\n> Figure 1:" in body and "[^1]: A footnote" in body


# --- 2.4 metadata ---------------------------------------------------------------------


def test_title_from_page_one_not_metadata(paper):
    assert pdf.extract(paper).title == TITLE


def test_bold_title_at_body_size(tmp_path):
    p = Page().text(150, 720, "A Bold Invented Title", font="B")
    for i in range(10):
        p.text(LEFT, 680 - 14 * i, f"invented body line {i} that is long enough to look like running text ok")
    assert pdf.extract(write_pdf(tmp_path / "b.pdf", [p])).title == "A Bold Invented Title"


def test_metadata_title_then_stem(tmp_path):
    lines = [Page().text(LEFT, 700 - 14 * i, f"plain invented line {i} with enough words to be body text")
             for i in range(1)]
    for i in range(10):
        lines[0].text(LEFT, 680 - 14 * i, f"more plain invented text on line {i} of the only page here")
    p1 = write_pdf(tmp_path / "meta.pdf", lines, {"Title": "Invented Metadata Title"})
    p2 = write_pdf(tmp_path / "Some Stem.pdf", lines, {"Title": "Microsoft Word - draft.docx"})
    assert pdf.extract(p1).title == "Invented Metadata Title"
    assert pdf.extract(p2).title == "Some Stem"


def test_authors_from_page_one(paper):
    assert pdf.extract(paper).authors == ["Anna Example", "Boris Sample"]


def test_authors_from_metadata(tmp_path):
    p = write_pdf(tmp_path / "m.pdf", paper_pages(), {"Author": "Carla Invented; Dmitri Madeup"})
    assert pdf.extract(p).authors == ["Carla Invented", "Dmitri Madeup"]


def test_no_recognisable_authors(tmp_path):
    pages = paper_pages()
    pages[0].items = [it for it in pages[0].items if "Example" not in it[4] and "Sample" not in it[4]
                      and it[4] not in ("1", "2")]
    p = write_pdf(tmp_path / "n.pdf", pages, {"Author": "jdoe"})
    assert pdf.extract(p).authors == []


def test_doi_and_pages(paper):
    d = pdf.extract(paper)
    assert d.doi == "10.1234/abcd.5678"
    assert d.pages == 3
    assert d.extractor.startswith("pdfminer.six ")


# --- 2.5 refusals -----------------------------------------------------------------------


def test_scanned_pdf_refused(tmp_path):
    with pytest.raises(WikiError) as e:
        pdf.extract(write_pdf(tmp_path / "scan.pdf", image_only_pages()))
    assert e.value.code == "no_text_layer"


def test_two_columns_refused(tmp_path):
    with pytest.raises(WikiError) as e:
        pdf.extract(write_pdf(tmp_path / "cols.pdf", two_column_pages()))
    assert e.value.code == "multi_column"


def test_single_column_with_centred_title_and_wide_caption_accepted(paper):
    pdf.extract(paper)  # centred title, centred author line and a figure box: not columns


def test_not_a_pdf(tmp_path):
    for name, data in (("text.pdf", b"just some invented text, not a PDF\n"),
                       ("cut.pdf", pdf_bytes(paper_pages())[:400])):
        (tmp_path / name).write_bytes(data)
        with pytest.raises(WikiError) as e:
            pdf.extract(tmp_path / name)
        assert e.value.code == "pdf_unreadable", name


def test_encrypted(tmp_path, monkeypatch, paper):
    from pdfminer import pdfdocument

    def locked(*a, **k):
        raise pdfdocument.PDFPasswordIncorrect()

    monkeypatch.setattr(pdfdocument.PDFDocument, "__init__", locked)
    with pytest.raises(WikiError) as e:
        pdf.extract(paper)
    assert e.value.code == "pdf_encrypted"



# --- 3. capture -------------------------------------------------------------------------

import datetime as dt  # noqa: E402
import hashlib  # noqa: E402

from llmwiki import lint, sources  # noqa: E402
from llmwiki.pages import parse  # noqa: E402
from llmwiki.vault import Vault  # noqa: E402

NOW = dt.datetime(2026, 10, 10, 12, 0, tzinfo=dt.timezone.utc)


def _files(root):
    return sorted(p.relative_to(root).as_posix() for p in (root / "raw").rglob("*") if p.is_file())


def test_capture_single_column_paper(run_cli, tmp_vault, paper):
    before = (paper.read_bytes(), paper.stat().st_mtime_ns)
    r = run_cli("add-source", paper, "--json", "--vault", tmp_vault.root)
    assert r.code == 0, r.out + r.err
    doc = r.json()
    assert doc["status"] == "pending" and doc["created"] is True and doc["kind"] == "file"
    raw = parse((tmp_vault.root / doc["path"]).read_text(encoding="utf-8"))
    m = raw.meta
    assert m["format"] == "pdf" and m["title"] == TITLE and m["pages"] == 3
    assert m["authors"] == ["Anna Example", "Boris Sample"] and m["doi"] == "10.1234/abcd.5678"
    assert m["original_sha256"] == hashlib.sha256(before[0]).hexdigest() and m["original_size"] == len(before[0])
    assert m["extractor"].startswith("pdfminer.six ") and m["original_path"] == str(paper.resolve())
    assert "published" not in m and "published_via" not in m
    assert (tmp_vault.root / m["original_file"]).read_bytes() == before[0]
    assert m["original_file"].startswith("raw/.orig/") and m["original_file"].endswith(".pdf")
    assert raw.body.startswith(f"# {TITLE}\n")
    assert (paper.read_bytes(), paper.stat().st_mtime_ns) == before


@pytest.mark.parametrize("make, code", [
    (lambda d: write_pdf(d / "scan.pdf", image_only_pages()), "no_text_layer"),
    (lambda d: write_pdf(d / "cols.pdf", two_column_pages()), "multi_column"),
    (lambda d: (d / "x.pdf", (d / "x.pdf").write_text("not a pdf"))[0], "pdf_unreadable"),
])
def test_refusals_write_nothing(run_cli, tmp_vault, tmp_path, make, code):
    r = run_cli("add-source", make(tmp_path), "--json", "--vault", tmp_vault.root)
    assert r.code == 2 and r.json()["error"]["code"] == code
    assert _files(tmp_vault.root) == []


def test_url_option_rejected(run_cli, tmp_vault, paper):
    r = run_cli("add-source", paper, "--url", "https://example.org/x", "--json", "--vault", tmp_vault.root)
    assert r.code == 2 and r.json()["error"]["code"] == "invalid_option"
    assert _files(tmp_vault.root) == []


def test_same_pdf_again_is_duplicate(tmp_vault, tmp_path, paper):
    v = Vault(tmp_vault.root)
    first = sources.capture(v, str(paper), now=NOW)
    copy = tmp_path / "elsewhere" / "renamed.pdf"
    copy.parent.mkdir()
    copy.write_bytes(paper.read_bytes())
    files = _files(tmp_vault.root)
    again = sources.capture(v, str(copy), now=NOW)
    assert again["duplicate_of"] == first["path"] and again["created"] is False
    assert _files(tmp_vault.root) == files


def test_same_pdf_duplicate_even_if_text_differs(tmp_vault, paper, monkeypatch):
    v = Vault(tmp_vault.root)
    first = sources.capture(v, str(paper), now=NOW)
    real = pdf.extract
    monkeypatch.setattr(pdf, "extract", lambda p: (lambda d: (setattr(d, "body", d.body + "\nnewer\n"), d)[1])(real(p)))
    assert sources.capture(v, str(paper), now=NOW)["duplicate_of"] == first["path"]


def _snapshot(root):
    return {p.relative_to(root).as_posix(): p.read_bytes() for p in root.rglob("*") if p.is_file()}


def test_source_meta_pdf(run_cli, tmp_vault, paper):
    res = sources.capture(Vault(tmp_vault.root), str(paper), now=NOW)
    before = _snapshot(tmp_vault.root)
    r = run_cli("source-meta", res["path"], "--json", "--vault", tmp_vault.root)
    assert r.code == 0, r.out + r.err
    doc = r.json()
    assert doc["derivable"] is True and doc["error"] is None
    assert doc["derived"]["title"] == TITLE and doc["derived"]["authors"] == ["Anna Example", "Boris Sample"]
    assert doc["derived"]["published"] is None
    assert _snapshot(tmp_vault.root) == before


def test_source_meta_pdf_not_on_this_machine(run_cli, tmp_vault, paper):
    res = sources.capture(Vault(tmp_vault.root), str(paper), now=NOW)
    for f in (tmp_vault.root / "raw" / ".orig").glob("*.pdf"):
        f.unlink()
    doc = run_cli("source-meta", res["path"], "--json", "--vault", tmp_vault.root).json()
    assert doc["derivable"] is False and doc["recorded"]["title"] == TITLE
    assert run_cli("source-meta", "--all", "--json", "--vault", tmp_vault.root).code == 0


# --- 4. lint -----------------------------------------------------------------------------


def test_lint_original_not_local(tmp_vault, paper):
    v = Vault(tmp_vault.root)
    res = sources.capture(v, str(paper), now=NOW)
    assert "original_not_local" not in {f.code for f in lint.check(v)}
    for f in (tmp_vault.root / "raw" / ".orig").glob("*.pdf"):
        f.unlink()
    found = [f for f in lint.check(v) if f.code == "original_not_local"]
    assert [(f.severity, f.path) for f in found] == [("info", res["path"])]
    assert all(f.severity == "info" for f in lint.check(v) if f.path == res["path"])


# --- 5. templates ----------------------------------------------------------------------------

import shutil  # noqa: E402
import subprocess  # noqa: E402

from llmwiki.languages import LANGUAGES  # noqa: E402
from llmwiki.scaffold import planned_files  # noqa: E402

PREVIOUS_GITIGNORE = """# Obsidian per-device workspace state
.obsidian/workspace*.json
.obsidian/cache
.trash/

# OS cruft
.DS_Store
Thumbs.db

# Claude Code per-user settings
.claude/settings.local.json

# Kimi Code per-machine settings
.kimi-code/local.toml
"""


@pytest.mark.skipif(not shutil.which("git"), reason="git not installed")
def test_stored_pdfs_ignored_html_not(run_cli, tmp_path, paper):
    root = tmp_path / "v"
    assert run_cli("init", root).code == 0
    v = Vault(root)
    sources.capture(v, str(paper), now=NOW)
    html = tmp_path / "page.html"
    html.write_text("<html><head><title>Invented Page</title><link rel='canonical' href='https://example.org/p'>"
                    "</head><body><article><h1>Invented Page</h1>" + "<p>Invented paragraph text that is long "
                    "enough to be extracted as the main article of this page.</p>" * 6 + "</article></body></html>")
    sources.capture(v, str(html), now=NOW)
    origs = sorted(p.relative_to(root).as_posix() for p in (root / "raw" / ".orig").iterdir())
    ignored = subprocess.run(["git", "-C", str(root), "check-ignore", *origs], capture_output=True, text=True).stdout
    assert [o for o in origs if o.endswith(".pdf")] == ignored.splitlines()
    assert any(o.endswith(".html") for o in origs)


def test_upgrade_adds_pdf_rule(run_cli, tmp_path):
    root = tmp_path / "v"
    run_cli("init", root, "--no-git")
    (root / ".gitignore").write_text(PREVIOUS_GITIGNORE)
    doc = run_cli("upgrade", "--json", "--vault", root).json()
    assert {i["path"]: i["action"] for i in doc["items"]}[".gitignore"] == "update"
    assert "raw/.orig/*.pdf" in (root / ".gitignore").read_text()


@pytest.mark.parametrize("lang", [None, *LANGUAGES])
def test_schema_mentions_pdfs(lang):
    text = planned_files(language=lang)["AGENTS.md"]
    assert "`.pdf`" in text and "single-column" in text and "text layer" in text
    assert "git-ignored" in text


def test_ingest_workflow_guides_long_papers():
    files = planned_files()
    claude, kimi = files[".claude/commands/wiki-ingest.md"], files[".agents/skills/wiki-ingest/SKILL.md"]
    assert claude.split("---", 2)[2] == kimi.split("---", 2)[2]
    for needle in ("multi_column", "no_text_layer", "section by section", "References",
                   "always confirm\n   the publication date with the human"):
        assert needle in claude, needle
